<template><SilkRoadWorkspace title="创建数字人口播"><section class="create"><header><span>DIGITAL HUMAN CREATE</span><h1>配置商品讲解人</h1><p>上传数字人形象，填写本地化口播和动作要求，生成品牌营销视频。</p></header><el-form label-position="top"><el-form-item label="关联营销项目"><el-select v-model="projectId"><el-option v-for="item in projects" :key="item.id" :label="item.product_name" :value="String(item.id)"/></el-select></el-form-item><el-form-item label="数字人形象"><el-upload drag :auto-upload="false" :limit="1" accept="image/*" :on-change="onImage"><el-icon><UploadFilled/></el-icon><div>上传商品讲解人或品牌口播人形象</div></el-upload></el-form-item><el-form-item label="本地化口播文案"><el-input v-model="speech" type="textarea" :rows="6" placeholder="填写面向目标市场的商品讲解文案"/></el-form-item><el-form-item label="动作与表达"><el-input v-model="motion" type="textarea" :rows="3" placeholder="例如：自然微笑，展示商品，重点卖点处配合手势"/></el-form-item><div class="actions"><el-button @click="router.push('/digital-human')">取消</el-button><el-button type="primary" :loading="submitting" :disabled="!image||!speech" @click="submit">创建数字人任务</el-button></div></el-form></section></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage,type UploadFile}from'element-plus';import{UploadFilled}from'@element-plus/icons-vue';import{useRoute,useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{projectAPI}from'@/api/project';import{digitalHumanAPI}from'@/api/digital-human';import type{MarketingProject}from'@/types/project';const route=useRoute(),router=useRouter(),projects=ref<MarketingProject[]>([]),projectId=ref(String(route.query.projectId||'')),speech=ref(''),motion=ref(''),image=ref<File>(),submitting=ref(false);const onImage=(file:UploadFile)=>{image.value=file.raw};const submit=async()=>{if(!image.value)return;submitting.value=true;try{const data=new FormData();data.append('image',image.value);data.append('speech_text',speech.value);data.append('motion_text',motion.value);data.append('marketing_use_case','跨境商品讲解');if(projectId.value)data.append('project_id',projectId.value);await digitalHumanAPI.generate(data);ElMessage.success('数字人口播任务已创建');router.push('/digital-human')}catch(e:any){ElMessage.error(e?.message||'任务创建失败')}finally{submitting.value=false}};onMounted(async()=>{projects.value=(await projectAPI.list({page_size:100})).items;if(!projectId.value&&projects.value[0])projectId.value=String(projects.value[0].id)})</script>
<style scoped>.create{max-width:800px;margin:0 auto}.create header{text-align:center;margin-bottom:24px}.create header span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.create h1{font-size:31px;margin:8px}.create header p{color:var(--text-secondary)}.create form{padding:26px;border:1px solid var(--border-primary);border-radius:20px;background:var(--bg-card)}.create .el-select,.create :deep(.el-upload){width:100%}.create :deep(.el-upload-dragger){width:100%;background:var(--bg-muted)}.actions{display:flex;justify-content:flex-end;gap:10px}</style>
